<script lang="ts">
  import {untrack,onDestroy} from 'svelte';
  import {GitPullRequest,RefreshCw,Plus,Search,FileCode,Check,CircleAlert} from 'lucide-svelte';
  import {api,type Account,type GitState,type Pull,type PullDetails,type PullFile,type PullCommit,type PullContext} from './api';
  import DiffView from './DiffView.svelte';
  import Modal from './Modal.svelte';
  let {repoId,git,accounts,onconnect,onchanged}:{repoId:number;git:GitState|null;accounts:Account[];onconnect:()=>void;onchanged:()=>void}=$props();
  let accountId=$state(0),page=$state(1),hasMore=$state(false),rows=$state<Pull[]>([]),context=$state<PullContext|null>(null),selected=$state<Pull|null>(null),detail=$state<PullDetails|null>(null);
  let loading=$state(false),detailLoading=$state(false),busy=$state(false),error=$state(''),notice=$state(''),query=$state('');
  let files=$state<PullFile[]>([]),filePage=$state(1),moreFiles=$state(false),fileQuery=$state(''),selectedFile=$state<PullFile|null>(null),filesLoading=$state(false);
  let commits=$state<PullCommit[]>([]),commitsLimited=$state(false),commit=$state('');
  let reviewEvent=$state('COMMENT'),reviewBody=$state(''),reviewQuery=$state(''),reviewPage=$state(0),checkQuery=$state(''),checkPage=$state(0),method=$state('merge');
  let showCreate=$state(false),title=$state(''),body=$state(''),base=$state(''),draft=$state(false);
  let pendingMerge=$state<{number:number;head:string;method:string;title:string}|null>(null);
  let listSequence=0,detailSequence=0,fileSequence=0,alive=true;
  const filtered=$derived(rows.filter(p=>[p.title,p.user.login,String(p.number),p.head.ref,p.base.ref].some(s=>s.toLocaleLowerCase().includes(query.toLocaleLowerCase()))));
  const visibleFiles=$derived(files.filter(f=>f.filename.toLocaleLowerCase().includes(fileQuery.toLocaleLowerCase())));
  const reviews=$derived((detail?.reviews??[]).filter(r=>[r.user.login,r.state,r.body??''].some(s=>s.toLocaleLowerCase().includes(reviewQuery.toLocaleLowerCase()))).slice().reverse());
  const checks=$derived((detail?.checks.runs??[]).filter(c=>[c.name,c.status,c.conclusion??''].some(s=>s.toLocaleLowerCase().includes(checkQuery.toLocaleLowerCase()))));
  const blockedReview=$derived.by(()=>{const latest=new Map<string,string>();for(const r of detail?.reviews??[])if(['APPROVED','CHANGES_REQUESTED','DISMISSED'].includes(r.state))latest.set(r.user.login,r.state);return [...latest.values()].includes('CHANGES_REQUESTED');});
  const canMerge=$derived(!busy&&!detailLoading&&!!detail&&detail.pull.state==='open'&&!detail.pull.draft&&detail.pull.mergeable===true&&['clean','has_hooks'].includes(detail.pull.mergeable_state??'')&&detail.checks.ready&&detail.checks.complete&&detail.reviews_complete&&!blockedReview&&detail.merge_methods.includes(method));
  const canCreate=$derived(!busy&&!!git?.head&&!git.dirty&&!git.operation&&!!git.upstream&&git.ahead===0&&git.branch!==base);
  $effect(()=>{const list=accounts;if(!list.some(a=>a.id===accountId))accountId=list[0]?.id??0;});
  $effect(()=>{repoId;accountId;untrack(()=>{if(accountId)void loadList(1);else{rows=[];context=null;selected=null;detail=null;++listSequence;++detailSequence;++fileSequence;}});});
  $effect(()=>{reviewQuery;reviewPage=0;});$effect(()=>{checkQuery;checkPage=0;});
  onDestroy(()=>{alive=false;++listSequence;++detailSequence;++fileSequence;});
  async function loadList(next:number){
    if(!accountId)return;const sequence=++listSequence;const id=repoId,account=accountId;loading=true;error='';selected=null;detail=null;files=[];commits=[];++detailSequence;++fileSequence;
    const results=await Promise.allSettled([api.pulls(id,account,next),api.pullContext(id,account)]);
    if(!alive||sequence!==listSequence)return;
    if(results[0].status==='fulfilled'){rows=results[0].value.items;hasMore=results[0].value.has_more;page=next;if(rows[0])void choose(rows[0]);}else{rows=[];error=String(results[0].reason);}
    if(results[1].status==='fulfilled'){context=results[1].value;base=context.default_branch;}else{context=null;error=String(results[1].reason);}
    loading=false;
  }
  async function choose(pull:Pull){
    const sequence=++detailSequence;const id=repoId,account=accountId;const same=selected?.number===pull.number;selected=pull;detail=null;files=[];selectedFile=null;commits=[];commit='';detailLoading=true;error='';++fileSequence;if(!same){reviewBody='';reviewEvent='COMMENT';}reviewPage=0;checkPage=0;
    const result=await Promise.allSettled([api.pullDetails(id,account,pull.number),api.pullCommits(id,account,pull.number)]);
    if(!alive||sequence!==detailSequence)return;
    if(result[0].status==='fulfilled'){detail=result[0].value;selected=detail.pull;method=detail.merge_methods[0]??'merge';void loadFiles(1);}else error=String(result[0].reason);
    if(result[1].status==='fulfilled'){commits=result[1].value.items;commitsLimited=result[1].value.has_more;}else error=String(result[1].reason);
    detailLoading=false;
  }
  async function loadFiles(next:number){if(!selected)return;const sequence=++fileSequence;const id=repoId,account=accountId,number=selected.number,sha=commit||null;filesLoading=true;selectedFile=null;fileQuery='';try{const result=await api.pullFiles(id,account,number,next,sha);if(alive&&sequence===fileSequence){files=result.items;moreFiles=result.has_more;filePage=next;selectedFile=files[0]??null;}}catch(e){if(alive&&sequence===fileSequence){files=[];error=String(e);}}finally{if(alive&&sequence===fileSequence)filesLoading=false;}}
  async function create(){if(!git?.head||!canCreate||!title.trim())return;const input={title,body,base,head:git.branch,expected_head:git.head,draft};const id=repoId,account=accountId;busy=true;error='';try{const result=await api.createPull(id,account,input);notice='Created pull request #'+result.number;showCreate=false;title='';body='';await loadList(1);await choose(result);}catch(e){error=String(e);}finally{busy=false;}}
  async function review(){if(!detail||busy||detailLoading)return;const number=detail.pull.number,head=detail.pull.head.sha,id=repoId,account=accountId,event=reviewEvent,text=reviewBody;busy=true;error='';try{await api.reviewPull(id,account,number,head,event,text);notice='Review submitted for #'+number;reviewBody='';if(selected?.number===number)await choose(selected);}catch(e){error=String(e);}finally{busy=false;}}
  function confirmMerge(){if(!detail||!canMerge)return;pendingMerge={number:detail.pull.number,head:detail.pull.head.sha,method,title:detail.pull.title};}
  async function merge(){if(!pendingMerge||busy)return;const snapshot=pendingMerge,id=repoId,account=accountId;busy=true;error='';try{notice=await api.mergePull(id,account,snapshot.number,snapshot.head,snapshot.method)+' Fetch to update your local refs.';pendingMerge=null;onchanged();await loadList(1);}catch(e){const message=String(e);pendingMerge=null;if(selected)await choose(selected);error=message;}finally{busy=false;}}
</script>

<section class="pull-requests" aria-label="Pull requests">
  <div class="pr-toolbar"><label>GitHub account<select aria-label="GitHub account for pull requests" bind:value={accountId} disabled={busy||loading}>{#each accounts as account}<option value={account.id}>@{account.login}</option>{/each}</select></label><div class="toolbar"><button class="secondary" disabled={busy||loading||!accountId} onclick={()=>loadList(page)}><RefreshCw size={15}/> Refresh</button><button class="primary" disabled={!accountId||!context||busy} onclick={()=>{showCreate=true;title='';body='';base=context?.default_branch??'';}}><Plus size={15}/> New pull request</button></div></div>
  {#if notice}<p class="inline-success" role="status">{notice}</p>{/if}{#if error}<p class="connection-error" role="alert">{error}</p>{/if}
  {#if !accounts.length}<div class="empty-block"><GitPullRequest size={28}/><p>Connect GitHub to review and manage pull requests.</p><button class="primary" onclick={onconnect}>Connect GitHub</button></div>
  {:else}<div class="pr-workbench"><section class="panel pr-list"><div class="panel-title">Open pull requests <span>{context?.full_name??''}</span></div><div class="search-input history-search"><Search size={15}/><input aria-label="Find pull requests" placeholder="Find in this page" bind:value={query}/></div><div class="commit-list">{#each filtered as pull (pull.number)}<button class="commit-choice" class:is-selected={selected?.number===pull.number} disabled={busy} onclick={()=>{if(selected?.number!==pull.number)void choose(pull);}}><GitPullRequest size={18}/><span><strong>{pull.title}</strong><small>#{pull.number} · @{pull.user.login}{pull.draft?' · Draft':''}</small><code>{pull.head.ref} → {pull.base.ref}</code></span></button>{:else}<p class="empty-small">{loading?'Loading pull requests…':query?'No matching pull requests':'No open pull requests'}</p>{/each}</div><div class="history-paging"><button class="secondary" disabled={busy||loading||page===1} onclick={()=>loadList(page-1)}>Previous</button><span>{page}</span><button class="secondary" disabled={busy||loading||!hasMore} onclick={()=>loadList(page+1)}>Next</button></div></section>
  <div class="pr-inspector">{#if detail&&selected}<section class="panel pr-summary"><div class="pr-title"><div><h2>#{detail.pull.number} {detail.pull.title}</h2><p>@{detail.pull.user.login} · {detail.pull.head.label} → {detail.pull.base.ref}</p></div><span class="pill" class:green={detail.pull.mergeable===true&&!detail.pull.draft} class:yellow={detail.pull.draft||detail.pull.mergeable!==true}>{detail.pull.draft?'Draft':detail.pull.mergeable===false?'Conflicts':detail.pull.mergeable===null?'Checking':'Open'}</span></div>{#if detail.pull.body}<pre class="pr-description">{detail.pull.body.slice(0,20000)}</pre>{/if}<code class="pr-head">Reviewed head: {detail.pull.head.sha.slice(0,12)}</code>
  <details class="pr-status"><summary>{#if detail.checks.ready}<Check size={15}/> Checks passed or not configured{:else}<CircleAlert size={15}/> Checks pending, failing or unavailable{/if}</summary>{#if detail.checks.runs.length>10}<input aria-label="Filter checks" placeholder="Filter checks" bind:value={checkQuery}/>{/if}<div class="check-list">{#each checks.slice(checkPage*10,checkPage*10+10) as check}<div><span>{check.name}</span><b class:change-added={check.conclusion==='success'} class:change-deleted={['failure','timed_out','cancelled'].includes(check.conclusion??'')}>{check.conclusion??check.status}</b></div>{/each}<p>Commit status: {detail.checks.legacy_state}</p>{#if !detail.checks.complete}<p>Check results are incomplete. Merge is blocked.</p>{/if}</div>{#if checks.length>10}<div class="history-paging"><button class="secondary" disabled={checkPage===0} onclick={()=>checkPage--}>Previous</button><span>{checkPage+1}</span><button class="secondary" disabled={(checkPage+1)*10>=checks.length} onclick={()=>checkPage++}>Next</button></div>{/if}</details>
  </section>
  <section class="panel pr-diff"><div class="pr-commit-picker"><label>Changes<select aria-label="Pull request commit" bind:value={commit} onchange={()=>loadFiles(1)}><option value="">All changes</option>{#each commits as item}<option value={item.sha}>{item.sha.slice(0,8)} · {item.commit.message.split('\n')[0].slice(0,100)}</option>{/each}</select></label>{#if commitsLimited}<small>First 100 commits. Use GitHub for older or additional commits.</small>{/if}</div><div class="history-files-and-diff"><section class="history-files"><div class="panel-title">Files · page {filePage}</div>{#if files.length>8}<input aria-label="Filter pull request files" placeholder="Filter files" bind:value={fileQuery}/>{/if}<div class="file-list">{#each visibleFiles as file (file.filename)}<button class="changed-file" class:file-selected={selectedFile?.filename===file.filename} onclick={()=>selectedFile=file}><FileCode size={15}/><span>{file.filename}</span><small class="change-added">+{file.additions}</small><small class="change-deleted">−{file.deletions}</small></button>{:else}<p class="empty-small">{filesLoading?'Loading files…':'No files on this page'}</p>{/each}</div><div class="history-paging"><button class="secondary" disabled={filesLoading||filePage===1} onclick={()=>loadFiles(filePage-1)}>Previous</button><button class="secondary" disabled={filesLoading||!moreFiles} onclick={()=>loadFiles(filePage+1)}>Next</button></div></section><section class="diff-panel"><div class="panel-title"><span class="diff-filename">{selectedFile?.filename??'Select a file'}</span></div>{#if filesLoading}<div class="diff-empty">Loading diff…</div>{:else if selectedFile?.patch}<DiffView code={selectedFile.patch} label="Pull request diff"/>{:else}<div class="diff-empty">No textual preview. The file may be binary or GitHub may have omitted its patch.</div>{/if}</section></div></section>
  <section class="panel pr-review"><h3>Submit a review</h3><div class="inline-form"><select aria-label="Review action" bind:value={reviewEvent} disabled={busy}><option value="COMMENT">Comment</option><option value="APPROVE">Approve</option><option value="REQUEST_CHANGES">Request changes</option></select></div><textarea aria-label="Review comment" placeholder="Review comment" maxlength="20000" rows="3" bind:value={reviewBody} disabled={busy}></textarea><button class="primary" disabled={busy||detailLoading||detail.pull.state!=='open'||(reviewEvent!=='APPROVE'&&!reviewBody.trim())} onclick={review}>{reviewEvent==='APPROVE'?'Approve pull request':reviewEvent==='REQUEST_CHANGES'?'Request changes':'Submit comment'}</button></section>
  <section class="panel pr-review-history"><h3>Reviews</h3>{#if detail.reviews.length>10}<input aria-label="Filter reviews" placeholder="Filter reviews" bind:value={reviewQuery}/>{/if}{#each reviews.slice(reviewPage*10,reviewPage*10+10) as review}<article><strong>@{review.user.login}</strong><span class:change-added={review.state==='APPROVED'} class:change-deleted={review.state==='CHANGES_REQUESTED'}>{review.state.replaceAll('_',' ')}</span>{#if review.body}<pre>{review.body.slice(0,20000)}</pre>{/if}</article>{:else}<p>No reviews</p>{/each}{#if reviews.length>10}<div class="history-paging"><button class="secondary" disabled={reviewPage===0} onclick={()=>reviewPage--}>Previous</button><span>{reviewPage+1}</span><button class="secondary" disabled={(reviewPage+1)*10>=reviews.length} onclick={()=>reviewPage++}>Next</button></div>{/if}{#if !detail.reviews_complete}<p>Review history is incomplete; merge is blocked.</p>{/if}</section>
  <section class="panel pr-merge"><div><h3>Merge pull request</h3><p>{canMerge?'GitHub policy and current checks allow a merge.':'Merge is blocked until conflicts, checks, reviews and repository rules are satisfied.'}</p></div><select aria-label="Merge method" bind:value={method} disabled={busy}>{#each detail.merge_methods as option}<option value={option}>{option==='squash'?'Squash and merge':option==='rebase'?'Rebase and merge':'Merge commit'}</option>{/each}</select><button class="primary" disabled={!canMerge} onclick={confirmMerge}>Merge…</button></section>
  {:else if detailLoading}<div class="empty-block" role="status">Loading pull request…</div>{/if}</div></div>{/if}
</section>
{#if showCreate}<Modal canClose={!busy} label="Create pull request" onclose={()=>{if(!busy)showCreate=false;}}><h2>Create pull request</h2><p>{context?.full_name} · {git?.branch??''}</p>{#if error}<p class="connection-error" role="alert">{error}</p>{/if}<label for="pr-base">Base branch</label><input id="pr-base" list="pr-base-options" bind:value={base}/><datalist id="pr-base-options">{#each context?.branches??[] as branch}<option value={branch}></option>{/each}</datalist><label for="pr-title">Title</label><input id="pr-title" bind:value={title} maxlength="256"/><label for="pr-body">Description</label><textarea id="pr-body" bind:value={body} rows="5" maxlength="20000"></textarea><label class="scope-choice"><input type="checkbox" bind:checked={draft}/>Draft pull request</label>{#if !canCreate}<p class="connection-error">Commit and publish this branch, then choose a different base branch.</p>{/if}<div class="modal-actions"><button class="secondary" disabled={busy} onclick={()=>showCreate=false}>Cancel</button><button class="primary" disabled={!canCreate||!title.trim()} onclick={create}>Create pull request</button></div></Modal>{/if}
{#if pendingMerge}<Modal canClose={!busy} label="Confirm pull request merge" onclose={()=>{if(!busy)pendingMerge=null;}}><h2>Merge #{pendingMerge.number}?</h2><p>{pendingMerge.title}</p><p>Method: {pendingMerge.method} · Head: {pendingMerge.head.slice(0,12)}</p><p>GitHub status and the reviewed commit will be checked again before merging.</p><div class="modal-actions"><button class="secondary" disabled={busy} onclick={()=>pendingMerge=null}>Cancel</button><button class="primary" disabled={busy} onclick={merge}>Merge pull request</button></div></Modal>{/if}
